#ifndef CSM_MOVE_H
#define CSM_MOVE_H

#include <stddef.h>

#include "rewrite.h"

enum note_level {
	NOTE_INFO,		/* what is done, for stdout */
	NOTE_WARNING,		/* something stays behind */
	NOTE_ERROR		/* something failed */
};

/*
 * A message for the user: a catalogue key with the arguments %1$s and
 * %2$s. When err is not 0, strerror(err) is the second argument instead.
 */
struct note {
	enum note_level level;
	const char *key;
	char *a, *b;
	int err;
};

/* One run of csm, over any number of repositories or session directories. */
struct move_ctx {
	char *home;		/* NULL when unknown */
	char *config_dir;	/* $CLAUDE_CONFIG_DIR or ~/.claude */
	char *projects_dir;	/* <config_dir>/projects */
	char *config_file;	/* .claude.json */
	char *data_dir;		/* csm's own data; NULL when unknown */
	int apply;		/* 0 only plans (-n) */
	int backup_done;	/* .claude.json.bak made in this run */
	int failed;		/* a warning or an error was noted */
	struct note *notes;
	size_t note_count, note_cap;
	struct change_list plan;
};

void move_init(struct move_ctx *ctx, int apply);
void move_clear(struct move_ctx *ctx);
void move_free(struct move_ctx *ctx);
int move_repo(struct move_ctx *ctx, const char *source, const char *target);
int move_fix(struct move_ctx *ctx, const char *old_path, const char *new_path);
int move_tree(const char *from, const char *to);
int move_merge(struct move_ctx *ctx, const char *from, const char *to,
    const char *kept);
void move_note(struct move_ctx *ctx, enum note_level level, const char *key,
    const char *a, const char *b, int err);
int claude_running(void);

#endif
